\title{A Parity-Uniform Cubic Upper Bound for $\ex(n, K_{a,b}, K_{3,t})$,\\
with Threshold Analysis and Downward Closure}
\author{Aristotle}
\date{2026-06-24}

\begin{document}
\maketitle

\begin{abstract}
We study the generalized (Alon--Shikhelman) Tur\'an problem of counting copies of the complete
bipartite graph $K_{a,b}$ inside graphs that forbid the smaller complete bipartite graph
$K_{3,t}$. We prove an explicit cubic upper bound: for every $K_{3,t}$-free graph $G$ on $n$
vertices with $3\le a$, $3\le b$, the number of labelled copies of $K_{a,b}$ is at most
$\binom{n}{3}\binom{t-1}{b}\binom{t-1}{a-3}$, hence $O(n^3)$. The argument is a
K\H{o}v\'ari--S\'os--Tur\'an-style double count anchored on a $3$-element core extracted from the
$a$-side of each copy, using the equivalence between $K_{3,t}$-freeness and a uniform cap of
$t-1$ on the common neighborhood of every triple. The bound holds uniformly at the conjectured
necessary threshold $t = b+1$ for every parity of $b$; the parity subtlety in the literature
lives entirely in the matching lower-bound construction. We complement the bound with an exact
threshold analysis: for $b\ge 6$ the proved Janzer--Longbrake--Yepremyan threshold
$2\max\{3,\lceil b/2\rceil\}+1$ equals $b+1+(b\bmod 2)$, so it coincides with the necessary
threshold $b+1$ exactly when $b$ is even and exceeds it by one exactly when $b$ is odd. Finally,
we establish downward closure: the cubic bound transfers verbatim, with the same constant, to
every subgraph of a $K_{3,t}$-free graph, making the estimate robust under edge deletion. All
results have been formally verified.
\end{abstract}

\section{Introduction}

\subsection{The generalized Tur\'an problem}
Classical extremal graph theory, initiated by Tur\'an, asks for the maximum number of edges in
an $n$-vertex graph avoiding a fixed subgraph. The Alon--Shikhelman generalization replaces
``number of edges'' by ``number of copies of a fixed pattern graph $H$'': for graphs $H$ and $F$,
\[
\ex(n, H, F) = \max\{\, c_H(G) : |V(G)| = n,\ G \text{ is } F\text{-free}\,\},
\]
where $c_H(G)$ is the number of labelled copies of $H$ in $G$. The classical case is $H = K_2$.

We focus on the bipartite-versus-bipartite instance $H = K_{a,b}$, $F = K_{3,t}$. The motivating
fact (a theorem of Janzer, Longbrake, and Yepremyan) is that for $t$ above a suitable threshold,
\[
\ex(n, K_{a,b}, K_{3,t}) = \Theta(n^3).
\]
The exponent $3$ is dictated by the ``$3$'' of the forbidden $K_{3,t}$: the three vertices on
the small side of the forbidden pattern are the only ones that may range freely, while all
remaining vertices of a $K_{a,b}$-copy are forced into bounded common neighborhoods.

\subsection{Contributions}
\begin{enumerate}
  \item \textbf{The cubic upper bound} (Section~\ref{sec:upper}). Any $K_{3,t}$-free graph on
  $n$ vertices contains at most $\binom{n}{3}\binom{t-1}{b}\binom{t-1}{a-3}$ copies of $K_{a,b}$,
  valid at the necessary threshold $t=b+1$ for every parity of $b$ (\texttt{KabCopies\_cubic\_of\_K3tFree}).
  \item \textbf{The threshold analysis} (Section~\ref{sec:threshold}). The gap between the proved
  threshold $2\max\{3,\lceil b/2\rceil\}+1$ and the necessary threshold $b+1$ equals $b\bmod 2$
  for $b\ge 6$ (\texttt{threshold\_gap}), is nonzero iff $b$ is odd
  (\texttt{necessary\_lt\_paper\_iff\_odd}), and the leading constant collapses to $\binom{b}{a-3}$
  at the necessary threshold (\texttt{cubic\_constant\_at\_threshold}).
  \item \textbf{Downward closure} (Section~\ref{sec:downward}). For $G\le G'$ with $G'$
  $K_{3,t}$-free, $G$ inherits the same cubic bound with the same constant
  (\texttt{KabCopies\_cubic\_of\_subgraph}).
\end{enumerate}

\section{Definitions}
Throughout, $V$ is a finite vertex set with $|V| = n$, and $G$ is a simple graph on $V$ with
adjacency relation $\sim$ (symmetric and irreflexive). We use the natural-number convention
$\binom{m}{k}=0$ for $k>m$.

\begin{definition}[Common neighborhood]
For $S\subseteq V$, $\ \Nbhd(S) = \{\, w\in V : \forall u\in S,\ u\sim w \,\}$.
\end{definition}

\begin{definition}[Copies of $K_{a,b}$]
A labelled copy of $K_{a,b}$ in $G$ is an ordered pair $(A,B)$ of disjoint subsets of $V$ with
$|A|=a$, $|B|=b$, and $\forall u\in A,\forall v\in B,\ u\sim v$. The set of all such pairs is
$\Copies_{a,b}(G)$ and its cardinality is $c_{K_{a,b}}(G)$.
\end{definition}

\begin{definition}[$K_{3,t}$-freeness]
$G$ is $K_{3,t}$-free if there is no pair $A,B\subseteq V$ with $|A|=3$, $|B|=t$,
$A\cap B=\varnothing$, and $\forall u\in A,\forall v\in B,\ u\sim v$.
\end{definition}

\begin{definition}[Common-neighborhood bound]
$G$ satisfies the common-neighborhood bound at $t$ if $\forall S\subseteq V,\ |S|=3 \Rightarrow
|\Nbhd(S)| \le t-1$.
\end{definition}

\begin{definition}[Subgraph order]
For graphs $G, G'$ on $V$, $G \le G'$ means $u\sim_G v \Rightarrow u\sim_{G'} v$.
\end{definition}

\begin{definition}[Thresholds]
The necessary threshold is $\tau_{\mathrm{nec}}(b) = b+1$. The proved threshold is
$\tau_{\mathrm{proved}}(b) = 2\max\{3,\lceil b/2\rceil\}+1$, with $\lceil b/2\rceil =
\lfloor (b+1)/2\rfloor$ over $\mathbb{N}$.
\end{definition}

\section{The cubic upper bound}\label{sec:upper}

\begin{lemma}[Antitonicity]
If $S\subseteq T$ then $\Nbhd(T)\subseteq \Nbhd(S)$.
\end{lemma}
\begin{proof}
If $w\in \Nbhd(T)$ then $w$ is adjacent to every vertex of $T\supseteq S$, hence to every vertex
of $S$.
\end{proof}

\begin{lemma}[Freeness $\iff$ neighborhood cap]\label{lem:equiv}
For $t\ge 1$, $G$ is $K_{3,t}$-free iff $G$ satisfies the common-neighborhood bound at $t$.
\end{lemma}
\begin{proof}
($\Rightarrow$) If a triple $S$ had $|\Nbhd(S)|\ge t$, choose $B\subseteq \Nbhd(S)$ with $|B|=t$;
then $S,B$ are disjoint (irreflexivity) and every $u\in S$ is adjacent to every $v\in B$, a
forbidden $K_{3,t}$. ($\Leftarrow$) A copy $(A,B)$ of $K_{3,t}$ has $B\subseteq \Nbhd(A)$ with
$|A|=3$, so $|\Nbhd(A)|\ge t > t-1$, violating the cap.
\end{proof}

\begin{lemma}[Cap extends to large sets]\label{lem:cap}
If $G$ satisfies the common-neighborhood bound at $t$ and $|B|\ge 3$, then $|\Nbhd(B)|\le t-1$.
\end{lemma}
\begin{proof}
Take a triple $S\subseteq B$; antitonicity gives $\Nbhd(B)\subseteq \Nbhd(S)$, so
$|\Nbhd(B)|\le |\Nbhd(S)|\le t-1$.
\end{proof}

\begin{lemma}[Fiber bound]\label{lem:fiber}
Suppose $G$ satisfies the common-neighborhood bound at $t$ and $3\le b$. For any fixed triple $S$
with $|S|=3$,
\[
\#\{(A,B)\in\Copies_{a,b}(G) : S\subseteq A\}\ \le\ \binom{t-1}{b}\binom{t-1}{a-3}.
\]
\end{lemma}
\begin{proof}
For a copy $(A,B)$ with $S\subseteq A$: every vertex of $B$ is adjacent to all of $S$, so
$B\subseteq \Nbhd(S)$ with $|\Nbhd(S)|\le t-1$ (Lemma~\ref{lem:cap}), giving at most
$\binom{t-1}{b}$ choices of $B$; every vertex of $A\setminus S$ is adjacent to all of $B$, so
$A\setminus S\subseteq \Nbhd(B)$ with $|\Nbhd(B)|\le t-1$ (since $|B|=b\ge 3$), giving at most
$\binom{t-1}{a-3}$ choices. The map $(A,B)\mapsto(A\setminus S, B)$ is injective on the fiber
(recover $A=(A\setminus S)\cup S$), so the fiber has size at most $\binom{t-1}{b}\binom{t-1}{a-3}$.
\end{proof}

\begin{lemma}[Anchoring]\label{lem:anchor}
If $3\le a$, then $\displaystyle c_{K_{a,b}}(G)\le \sum_{|S|=3}\#\{(A,B)\in\Copies_{a,b}(G):
S\subseteq A\}$.
\end{lemma}
\begin{proof}
Each copy's $a$-side has $\binom{a}{3}\ge 1$ triples; exchanging summation order,
$c_{K_{a,b}}(G) = \sum_{(A,B)} 1 \le \sum_{(A,B)}\binom{|A|}{3} = \sum_{|S|=3}\#\{(A,B):S\subseteq A\}$.
\end{proof}

\begin{theorem}[Main upper bound]\label{thm:main}
If $G$ satisfies the common-neighborhood bound at $t$ with $3\le a$, $3\le b$, then
\[
c_{K_{a,b}}(G)\ \le\ \binom{n}{3}\,\binom{t-1}{b}\binom{t-1}{a-3}.
\]
\end{theorem}
\begin{proof}
Combine Lemma~\ref{lem:anchor} with Lemma~\ref{lem:fiber} on each of the $\binom{n}{3}$ triples.
\end{proof}

\begin{theorem}[Cubic bound for $K_{3,t}$-free graphs]\label{thm:cubic}
If $G$ is $K_{3,t}$-free with $3\le a$, $3\le b$, $b+1\le t$, then
\[
c_{K_{a,b}}(G)\ \le\ \binom{t-1}{b}\binom{t-1}{a-3}\cdot n^3 = O(n^3).
\]
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:equiv}, $K_{3,t}$-freeness gives the common-neighborhood bound at $t$ (using
$t\ge b+1\ge1$). Apply Theorem~\ref{thm:main} and $\binom{n}{3}\le n^3$.
\end{proof}

\begin{remark}[Why the exponent is exactly $3$]
The anchor $S$ contributes the $\binom{n}{3}\le n^3$ factor; all remaining $a+b-3$ vertices are
confined to common neighborhoods of size $\le t-1$ and contribute only the constant
$\binom{t-1}{b}\binom{t-1}{a-3}$. Replacing $K_{3,t}$ by $K_{s,t}$ would yield $\Theta(n^s)$.
\end{remark}

\begin{remark}[Role of the threshold hypothesis]
The hypothesis $t\ge b+1$ is not used by the upper bound itself: when $t-1<b$ the factor
$\binom{t-1}{b}$ vanishes and the bound correctly reports zero. It is retained because it is the
regime where a matching $\Omega(n^3)$ lower bound becomes possible.
\end{remark}

\section{The threshold analysis}\label{sec:threshold}

\begin{theorem}[Closed form]\label{thm:closed}
For $b\ge 6$, $\ \tau_{\mathrm{proved}}(b) = b + 1 + (b\bmod 2)$.
\end{theorem}
\begin{proof}
For $b\ge 6$, $\lceil b/2\rceil\ge 3$, so $\max\{3,\lceil b/2\rceil\}=\lceil b/2\rceil$ and
$2\lceil b/2\rceil = b + (b\bmod 2)$; add $1$.
\end{proof}

\begin{corollary}
For even $b\ge 6$, $\tau_{\mathrm{proved}}(b) = \tau_{\mathrm{nec}}(b) = b+1$.
\end{corollary}
\begin{corollary}
For odd $b\ge 6$, $\tau_{\mathrm{proved}}(b) = \tau_{\mathrm{nec}}(b)+1 = b+2$.
\end{corollary}

\begin{theorem}[Threshold gap]\label{thm:gap}
For $b\ge 6$, $\ \tau_{\mathrm{proved}}(b) - \tau_{\mathrm{nec}}(b) = b\bmod 2$.
\end{theorem}

\begin{theorem}[The frontier is exactly the odd case]
For $b\ge 6$, $\ \tau_{\mathrm{nec}}(b) < \tau_{\mathrm{proved}}(b) \iff b$ is odd.
\end{theorem}
\begin{proof}
Immediate from Theorem~\ref{thm:gap}, since $b\bmod 2 > 0\iff b$ odd.
\end{proof}

\begin{theorem}[Constant collapse]\label{thm:collapse}
At $t=\tau_{\mathrm{nec}}(b)=b+1$, $\ \binom{t-1}{b}\binom{t-1}{a-3} = \binom{b}{a-3}$.
\end{theorem}
\begin{proof}
With $t-1=b$, $\binom{b}{b}=1$.
\end{proof}

The $b\ge 6$ guard is load-bearing: for small $b$ the $\max$ clause dominates and the closed form
fails. The upper bound of Section~\ref{sec:upper} requires only $t\ge b+1$ and is parity-blind.
Thus the only obstruction to a sharp $\Theta(n^3)$ at the necessary threshold is the odd-$b$
off-by-one in the lower-bound construction.

\section{Downward closure}\label{sec:downward}

\begin{lemma}[Monotone common neighborhoods]
If $G\le G'$, then $\Nbhd_G(S)\subseteq \Nbhd_{G'}(S)$ for every $S$.
\end{lemma}
\begin{proof}
If $w\in \Nbhd_G(S)$ then $u\sim_G w$ for all $u\in S$, hence $u\sim_{G'}w$, so $w\in\Nbhd_{G'}(S)$.
\end{proof}

\begin{lemma}[Antitone freeness]\label{lem:anti}
If $G\le G'$ and $G'$ is $K_{3,t}$-free, then $G$ is $K_{3,t}$-free.
\end{lemma}
\begin{proof}
A copy of $K_{3,t}$ in $G$ has all cross edges in $G\subseteq G'$, a copy in $G'$ --- impossible.
\end{proof}

\begin{lemma}[Monotone neighborhood sizes]
If $G\le G'$, then $|\Nbhd_G(S)|\le|\Nbhd_{G'}(S)|$ for every $S$.
\end{lemma}

\begin{theorem}[Downward closure of the cubic bound]\label{thm:downward}
Let $G\le G'$ with $3\le a$, $3\le b$, $b+1\le t$, and $G'$ $K_{3,t}$-free. Then
\[
c_{K_{a,b}}(G)\ \le\ \binom{t-1}{b}\binom{t-1}{a-3}\cdot n^3,
\]
the same cubic bound, with the same constant, as for $G'$.
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:anti}, $G$ is $K_{3,t}$-free; apply Theorem~\ref{thm:cubic} to $G$.
\end{proof}

The estimate, once established for a dense $K_{3,t}$-free host $G'$, descends automatically to
every subgraph beneath it in the partial order of graphs. In deletion arguments, the surviving
graph after cleaning is such a subgraph, so its copy count is controlled without re-running the
double count.

\section{Algorithms}
\begin{description}
  \item[Algorithm A (Triple cap check)] For every triple $S$, compute $\Nbhd(S) =
  \bigcap_{u\in S}\mathcal{N}(u)$ and test $|\Nbhd(S)|\le t-1$. Complexity $O(n^4)$, or $O(n^3)$
  with bitset neighborhoods. Certifies the hypothesis of Theorem~\ref{thm:cubic}.
  \item[Algorithm B (Bound evaluator)] Return $\binom{t-1}{b}\binom{t-1}{a-3}\cdot n^3$ and the
  sharper $\binom{n}{3}\binom{t-1}{b}\binom{t-1}{a-3}$; at $t=b+1$ this is $\binom{b}{a-3}\cdot n^3$
  by Theorem~\ref{thm:collapse}. Complexity $O(1)$.
  \item[Algorithm C (Threshold comparator)] For $b\ge 6$, compute $\tau_{\mathrm{proved}}$,
  $\tau_{\mathrm{nec}}$, the gap $b\bmod 2$, and ``frontier open'' $= [b\text{ odd}]$. Complexity
  $O(1)$.
\end{description}

\section{Applications}
\begin{itemize}
  \item \textbf{Cleaning/deletion arguments.} Downward closure (Theorem~\ref{thm:downward}) lets
  surviving subgraphs inherit the cubic bound for free.
  \item \textbf{Supersaturation base camp.} Monotone bounds are natural starting points for
  averaging-over-subgraphs supersaturation.
  \item \textbf{Certified extremal counting.} Algorithms A--B form a verifiable pipeline:
  certify $K_{3,t}$-freeness, then emit a provably correct cubic bound.
\end{itemize}

\section{Discussion and future directions}
The results isolate the upper half of $\ex(n,K_{a,b},K_{3,t})=\Theta(n^3)$; the matching lower
bound, where the parity subtlety resides, is left open. The hypotheses $3\le a$, $3\le b$ are
genuine. Future directions: (1) abstract the monotonicity wrappers into a generic
forbidden-configuration interface that downward-closes every catalog bound; (2) a formal
deletion/cleaning combinator with ``copies lost'' accounting; (3) matching lower-bound
constructions at the necessary threshold, beginning with even $b$; (4) density and supersaturation
versions built on the monotonicity infrastructure.

\section{Conclusion}
A single principle --- capping the common neighborhood of every triple at $t-1$ --- yields,
through an anchored double count, an explicit and parity-uniform cubic upper bound
$\binom{n}{3}\binom{t-1}{b}\binom{t-1}{a-3}$ for $K_{a,b}$-copies in $K_{3,t}$-free graphs. An
exact arithmetic analysis locates the remaining frontier of the sharp problem in the parity of
$b$, and order-theoretic monotonicity makes the bound robust under deletion. The cubic exponent
is the ``$3$'' of the forbidden $K_{3,t}$, fossilized in the answer.

